const lessons=[{"sentences":[{"speaker":"A","text":"Hello I need to change my train booking because our morning meeting was delayed.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.7988333333333335},{"speaker":"B","text":"I can help you modify that reservation for the afternoon if seats remain.","position":2,"audioStartSeconds":4.998833333333334,"audioEndSeconds":9.823416666666667},{"speaker":"A","text":"That would be wonderful because otherwise I will miss the client presentation.","position":3,"audioStartSeconds":10.023416666666666,"audioEndSeconds":14.727791666666667},{"speaker":"B","text":"Let me check the system for you although the three o'clock express is full.","position":4,"audioStartSeconds":14.927791666666666,"audioEndSeconds":19.49041666666667},{"speaker":"A","text":"If that train is unavailable any later time before six o'clock works.","position":5,"audioStartSeconds":19.690416666666668,"audioEndSeconds":24.767708333333335},{"speaker":"B","text":"Good news as there are two seats left on the four thirty service.","position":6,"audioStartSeconds":24.967708333333334,"audioEndSeconds":29.091416666666667},{"speaker":"A","text":"Please book that one and send the updated ticket to my email.","position":7,"audioStartSeconds":29.291416666666667,"audioEndSeconds":33.337833333333336},{"speaker":"A","text":"Good morning I am here to collect the revised itinerary for my upcoming trip.","role":"section-start","position":8,"audioStartSeconds":38.337833333333336,"audioEndSeconds":43.337833333333336},{"speaker":"B","text":"Welcome and I have already printed the new travel documents for your review.","position":9,"audioStartSeconds":43.53783333333333,"audioEndSeconds":48.22858333333333},{"speaker":"A","text":"Did the agency manage to secure the hotel room near the conference center?","position":10,"audioStartSeconds":48.428583333333336,"audioEndSeconds":53.00333333333333},{"speaker":"B","text":"Yes they did although the nightly rate is slightly higher than our budget.","position":11,"audioStartSeconds":53.20333333333333,"audioEndSeconds":57.430125},{"speaker":"A","text":"That is acceptable because staying close will save us significant commuting time.","position":12,"audioStartSeconds":57.630125,"audioEndSeconds":62.70741666666667},{"speaker":"B","text":"Here is the folder containing your train tickets and the hotel confirmation details.","position":13,"audioStartSeconds":62.90741666666667,"audioEndSeconds":68.12783333333333},{"speaker":"A","text":"Thank you very much for organizing everything so quickly before my departure.","position":14,"audioStartSeconds":68.32783333333333,"audioEndSeconds":73.441}],"questions":[{"prompt":"Why does the customer want to change the train booking?","options":["Because the morning meeting was delayed.","Because the client cancelled the appointment.","Because the train ticket was too expensive."],"answer":"A","evidenceSentence":1,"evidence":"Hello I need to change my train booking because our morning meeting was delayed.","explanation":"Người nói A giải thích rằng cuộc họp buổi sáng bị hoãn nên cần đổi vé."},{"prompt":"What train departure time does the agent finally book?","options":["Three o'clock express.","Four thirty service.","Six o'clock train."],"answer":"B","evidenceSentence":6,"evidence":"Good news as there are two seats left on the four thirty service.","explanation":"Nhân viên thông báo còn chỗ trên chuyến bốn giờ rưỡi và tiến hành đặt chuyến đó."},{"prompt":"What should the agent do next after booking?","options":["Call the client directly.","Print the tickets at the desk.","Send the updated ticket by email."],"answer":"C","evidenceSentence":7,"evidence":"Please book that one and send the updated ticket to my email.","explanation":"Khách hàng yêu cầu gửi vé đã cập nhật qua địa chỉ email."},{"prompt":"What is the second conversation mainly about?","options":["Collecting a revised travel itinerary.","Cancelling a hotel reservation.","Booking a flight to another city."],"answer":"A","evidenceSentence":8,"evidence":"Good morning I am here to collect the revised itinerary for my upcoming trip.","explanation":"Khách hàng đến để lấy lịch trình đi lại đã được chỉnh sửa cho chuyến công tác."},{"prompt":"What does the agent say about the hotel room cost?","options":["It is completely free of charge.","It is slightly higher than the budget.","It is much cheaper than expected."],"answer":"B","evidenceSentence":11,"evidence":"Yes they did although the nightly rate is slightly higher than our budget.","explanation":"Nhân viên cho biết giá phòng khách sạn cao hơn một chút so với ngân sách."},{"prompt":"What is inside the folder given to the customer?","options":["Train tickets and hotel confirmation.","Conference schedule and speech notes.","Company financial reports and maps."],"answer":"A","evidenceSentence":13,"evidence":"Here is the folder containing your train tickets and the hotel confirmation details.","explanation":"Nhân viên đưa cho khách thư mục chứa vé tàu và chi tiết xác nhận khách sạn."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
